exercises.solution:
using System;
using System.Collections.Generic;
using System.Linq;

public static class Above
{
    public static List<int> AboveAverage(int[] nums)
    {
        if (nums.Length == 0) return new List<int>();
        double avg = nums.Average();
        return nums.Where(n => n > avg).ToList();
    }
}
